pub(crate) const STYLES: &str = r#"
.df-exploration{--gold:#d9b77a;--muted:#b4aca0;--ink:#141310;background:var(--ink);color:#f4eddf;overflow-wrap:anywhere}.df-exploration *{min-width:0}.df-exploration [hidden]{display:none!important}.df-exploration .scene-art{object-position:center 40%}.df-exploration:before{background:linear-gradient(180deg,#12100a80,transparent 20%,#14131018 40%,#141310e8 76%,#141310),linear-gradient(90deg,#11100db3,transparent 65%)}
.df-exploration .topbar{padding:22px 4vw;border-bottom:1px solid #d9b77a24;background:linear-gradient(#11100a99,transparent)}.df-exploration .brand{font-size:26px;letter-spacing:-1px;color:#efce91}.df-exploration .brand span{color:#e4d7bc}.df-exploration .preview-badge{font-size:9px;letter-spacing:1.2px;color:#c7b48f;border:0;border-left:1px solid #d9b77a66;border-radius:0;padding:6px 0 6px 12px;background:none}.df-exploration .overline{color:var(--gold)}
.df-exploration .stage{width:min(1600px,92%);min-height:430px;padding:140px 0 32px;gap:5vw;grid-template-columns:minmax(0,1fr) 280px}.df-exploration .chapter{font-size:10px;line-height:1.7;letter-spacing:2.5px;margin-bottom:14px;flex-wrap:wrap;gap:12px}.df-exploration h1{font-size:clamp(46px,5.5vw,80px);line-height:1.05;margin-bottom:18px;max-width:900px}.df-exploration .description{font-size:18px;line-height:1.65;max-width:620px;color:#eee5d5;text-shadow:0 2px 8px #000}.df-exploration .location{font-size:10px;line-height:1.7;letter-spacing:2px;margin-top:20px;color:#d5c5a6}
.df-exploration .scene-panel{padding:20px 22px;border:1px solid #c7a86b4d;border-radius:10px;background:linear-gradient(135deg,#24211bee,#181713ee);box-shadow:0 16px 45px #0004}.df-exploration .scene-panel h2{font-size:24px;margin:8px 0 12px;color:#f1dfbd}.df-exploration .objective{border-top-color:#d9b77a24;color:#b4aca0}.df-exploration .objective[data-state=active]{color:#f0d9ad}
.df-exploration .exploration-interaction{width:min(1600px,92%);margin:0 auto 24px;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:28px;align-items:start}.df-exploration .exploration-npc,.df-exploration .exploration-actions{padding:24px;border:1px solid #c7a86b4d;border-radius:10px;background:linear-gradient(135deg,#24211bf5,#181713f5);box-shadow:0 12px 35px #0003}.df-exploration .exploration-npc{display:flex;align-items:flex-start;gap:20px;border-left:2px solid #cba46680}.df-exploration .exploration-portrait{width:80px;height:100px;border-radius:40px 40px 6px 6px;border:1px solid #cba46699;object-fit:cover;flex:none;box-shadow:0 5px 18px #0004}.df-exploration .exploration-portrait-failed{display:none}.df-exploration .exploration-npc-text,.df-exploration .narration,.df-exploration .narration>div{min-width:0}.df-exploration .exploration-npc-name{margin:0;font-size:27px;font-weight:400;line-height:1.3;color:#f1dfbd}.df-exploration .exploration-context{font:10px/1.7 system-ui,sans-serif;letter-spacing:1px;color:#c5b99e;margin:6px 0 12px}.df-exploration .exploration-dialogue{font-size:19px;line-height:1.65;margin:0;color:#eee5d5}
.df-exploration .exploration-heading{margin:0 0 17px;font-size:25px;font-weight:400;line-height:1.3;color:#f1dfbd}.df-exploration .exploration-choices{display:grid;gap:10px}.df-exploration .exploration-choice{border:1px solid #a98b574d;border-radius:6px;background:#29251e;overflow:hidden;box-shadow:inset 0 1px 0 #fff1}.df-exploration .exploration-choice button{display:block;width:100%;text-align:left;font:16px/1.5 Georgia,serif;border:0;border-radius:0;color:#f1dfbd;padding:12px 16px;min-height:48px;background:none;letter-spacing:0;touch-action:manipulation}.df-exploration .exploration-choice:focus-within{border-color:#f1d69b}.df-exploration .exploration-choice button:hover:enabled{background:#42382a;color:#f6dfb5}.df-exploration button:disabled{cursor:default;color:#b4aca0;background:#1d1c17;border-color:#8c806b3d;opacity:1;box-shadow:none}.df-exploration button[aria-busy=true]{border-style:dashed}.df-exploration .exploration-choice-detail,.df-exploration .exploration-choice-reason{font:11px/1.65 system-ui,sans-serif;color:#c5b99e;padding:0 16px;margin:0 0 12px;overflow-wrap:anywhere}.df-exploration .exploration-choice-reason:empty{display:none}.df-exploration .exploration-choice-reason{color:#f0b9a3}
.df-exploration .df-ui-field{margin-top:19px}.df-exploration .df-ui-field label{display:block;font:12px/1.6 system-ui,sans-serif;color:#c5b99e}.df-exploration .df-ui-field label span{display:block;margin-bottom:8px}.df-exploration input{width:100%;min-height:48px;border:1px solid #a3916b59;border-radius:6px;background:#161510;color:#f4eddf;padding:11px 13px;font:15px/1.5 system-ui,sans-serif}.df-exploration input[readonly]{color:#b4aca0;background:#1d1c17}.df-exploration input[aria-invalid=true]{border-color:#dfa390}.df-exploration :focus-visible{outline:3px solid #f1d69b;outline-offset:4px}.df-exploration .df-ui-feedback{font:12px/1.65 system-ui,sans-serif;color:#dcc393;margin:8px 0;overflow-wrap:anywhere}.df-exploration .df-ui-feedback:empty{display:none}.df-exploration .exploration-submit{margin-top:10px;min-height:48px;min-width:160px;border:1px solid #a98b574d;border-radius:6px;color:#ede2cb;background:#29251e;padding:11px 16px;touch-action:manipulation}.df-exploration .exploration-submit:enabled{background:linear-gradient(135deg,#e3c592,#b99151);color:#211b11;border-color:#e9c78d;font-weight:650;box-shadow:0 5px 20px #9f6b3026,inset 0 1px 0 #fff6}.df-exploration .exploration-submit:hover:enabled{background:#edcea0}.df-exploration .exploration-empty{font:12px/1.7 system-ui,sans-serif;color:#b4aca0;margin:0 0 12px}
.df-exploration .lower{width:min(1600px,92%);grid-template-columns:minmax(0,1fr) 280px;gap:28px;padding-bottom:25px}.df-exploration .narration{padding:22px 26px;gap:20px;border-color:#c7a86b4d;border-radius:10px;background:linear-gradient(105deg,#24211bf5,#181713f5);box-shadow:0 12px 35px #0003}.df-exploration .narration:before{background:#24211b;color:var(--gold)}.df-exploration .narrator{width:64px;height:64px;border-color:#cba46699}.df-exploration .narration blockquote{font-size:18px;line-height:1.65;color:#eee5d5}.df-exploration .party-heading{flex-wrap:wrap;gap:8px}.df-exploration .party-card{padding:12px 15px;border-color:#c7a86b3d;border-radius:6px;background:#24211be8}.df-exploration .member-role{color:#b4aca0}.df-exploration .sigil{border-color:#cba46659;color:#dfbc7c}.df-exploration .connection{color:#b4aca0;font-size:10px;line-height:1.7}
.df-exploration .exploration-art-fallback{display:none;width:min(1600px,92%);margin:0 auto 25px;padding:12px 16px;border-left:2px solid #cba46673;background:#b78c4212;font:12px/1.7 system-ui,sans-serif;color:#d8cbb2}.df-exploration.exploration-art-failed .scene-art{display:none}.df-exploration.exploration-art-failed .exploration-art-fallback{display:block}.df-exploration.exploration-art-failed:before{background:linear-gradient(140deg,#342c1d66,#141310 65%)}
.df-exploration .exploration-checks{width:min(1600px,92%);margin:20px auto 30px;padding-top:20px;border-top:1px solid #ad925d55}.df-exploration .exploration-checks summary{min-height:44px;color:#dfb974;cursor:pointer}.df-exploration .exploration-fixture-controls{display:flex;flex-wrap:wrap;gap:8px}.df-exploration .exploration-check-status{font:12px/1.7 system-ui,sans-serif;color:#b4aca0}
@media(min-width:1600px){.df-exploration .stage{min-height:540px;padding-top:200px}.df-exploration .exploration-interaction,.df-exploration .lower{gap:40px}.df-exploration .exploration-npc,.df-exploration .exploration-actions{padding:28px}.df-exploration .exploration-dialogue,.df-exploration .narration blockquote{font-size:21px}}
@media(max-width:1000px){.df-exploration .stage{grid-template-columns:minmax(0,1fr) 240px;gap:24px;min-height:380px;padding-top:100px}.df-exploration .exploration-interaction{gap:20px}.df-exploration .exploration-npc,.df-exploration .exploration-actions{padding:20px}.df-exploration .exploration-npc{gap:15px}.df-exploration .exploration-portrait{width:64px;height:82px}.df-exploration .lower{grid-template-columns:minmax(0,1fr) 240px;gap:20px}}
@media(max-width:700px){.df-exploration .topbar{padding:17px 5vw;gap:12px;flex-wrap:wrap}.df-exploration .brand{font-size:23px}.df-exploration .preview-badge{font-size:8px;line-height:1.6;letter-spacing:1px;padding-left:9px;max-width:180px}.df-exploration .scene-art{height:440px;object-position:48% center}.df-exploration:before{background:linear-gradient(180deg,#14131050,transparent 14%,#141310b3 30%,#141310 440px)}.df-exploration .stage{display:block;min-height:0;padding:88px 0 20px;width:90%}.df-exploration .chapter{font-size:9px;letter-spacing:2px;margin-bottom:10px;gap:10px}.df-exploration .chapter:before{width:28px}.df-exploration h1{font-size:37px;letter-spacing:-1px;margin-bottom:12px}.df-exploration .description{font-size:15px;line-height:1.6}.df-exploration .location{font-size:9px;letter-spacing:1.5px;margin-top:15px}.df-exploration .scene-panel{margin-top:18px;padding:13px 16px;border-radius:8px;background:linear-gradient(135deg,#27241ded,#1c1a15ed);box-shadow:0 8px 22px #0002}.df-exploration .scene-panel h2{font-size:20px;margin:5px 0 0}.df-exploration .scene-panel .overline{font-size:9px;letter-spacing:2px}.df-exploration .objective{padding-top:10px;padding-bottom:10px}.df-exploration .exploration-interaction{width:90%;grid-template-columns:1fr;gap:16px;margin-bottom:22px}.df-exploration .exploration-npc,.df-exploration .exploration-actions{padding:17px;border-radius:8px}.df-exploration .exploration-npc{gap:13px}.df-exploration .exploration-dialogue{font-size:16px;line-height:1.6}.df-exploration .exploration-portrait{width:52px;height:66px}.df-exploration .exploration-npc-name{font-size:23px}.df-exploration .exploration-context{font-size:9px;margin:5px 0 8px}.df-exploration .exploration-heading{font-size:23px;margin-bottom:13px}.df-exploration .exploration-choice button{padding:11px 13px;font-size:15px;min-height:46px}.df-exploration .exploration-choice-detail,.df-exploration .exploration-choice-reason{padding:0 13px;margin-bottom:10px;font-size:11px}.df-exploration .df-ui-field{margin-top:15px}.df-exploration .exploration-submit{width:100%;min-width:0;min-height:46px;font-size:13px}.df-exploration .lower{width:90%;display:flex;gap:22px}.df-exploration .narration{padding:18px 16px;gap:13px;border-radius:8px}.df-exploration .narrator{width:46px;height:46px}.df-exploration .narration blockquote{font-size:15px;line-height:1.6;margin-top:8px}.df-exploration .narration .overline{font-size:9px;letter-spacing:1.5px}.df-exploration .party-heading{gap:6px}.df-exploration .party-heading .overline{font-size:9px;letter-spacing:1.7px}.df-exploration .exploration-fixture-controls button{flex-basis:100%}.df-exploration .exploration-art-fallback{width:90%}}
@media(max-width:360px){.df-exploration .preview-badge{max-width:135px;font-size:7px}.df-exploration .brand{font-size:21px}.df-exploration .stage{padding-top:76px}.df-exploration h1{font-size:33px}.df-exploration .exploration-npc,.df-exploration .exploration-actions{padding:15px}}
@media(prefers-reduced-motion:reduce){.df-exploration *,.df-exploration *:before,.df-exploration *:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
"#;
